diff --git a/src/ops/linear/q4/q4_rowsplit_gemm_mma_sm120a.cu b/src/ops/linear/q4/q4_rowsplit_gemm_mma_sm120a.cu
new file mode 100644
index 00000000..7068aae3
--- /dev/null
+++ b/src/ops/linear/q4/q4_rowsplit_gemm_mma_sm120a.cu
@@ -0,0 +1,92 @@
+#include "ops/linear/q4/q4_rowsplit_gemm_mma.cuh"
+
+#include "core/device.h"
+#include "ops/common/math.h"
+#include "ops/common/token_slices.h"
+#include "ops/linear/q4/q4_launch.h"
+
+#include <cstdint>
+#include <stdexcept>
+
+namespace ginfer::ops::detail {
+namespace {
+
+#if defined(GINFER_COMPILED_CC) && GINFER_COMPILED_CC >= 120
+using Q4MmaSm120R32C40Schedule =
+    Q4RowSplitMmaGemmSchedule<32, 40, 128, 16, 8, 2, 2, Q4FragmentPipeline::Serial, Cache::cg,
+                              Cache::cg, Q4ScaleLoad::Pair32>;
+
+using Q4MmaSm120R32C48Schedule =
+    Q4RowSplitMmaGemmSchedule<32, 48, 64, 16, 8, 2, 4, Q4FragmentPipeline::Serial, Cache::cg,
+                              Cache::cg, Q4ScaleLoad::Pair32>;
+
+using Q4MmaSm120R64C40K128Schedule =
+    Q4RowSplitMmaGemmSchedule<64, 40, 128, 32, 8, 2, 1, Q4FragmentPipeline::Serial, Cache::cg,
+                              Cache::cg, Q4ScaleLoad::Pair32>;
+
+template <class Schedule, bool Full>
+void launch_schedule(const Tensor& x, const Weight& w, Tensor& out, cudaStream_t stream) {
+    const std::int32_t rows     = out.ne[0];
+    const std::int32_t k        = x.ne[0];
+    const std::int32_t cols     = x.ne[1];
+    const std::int32_t padded_k = w.padded_shape[1];
+
+    const dim3 grid(static_cast<unsigned>(div_up(rows, Schedule::kBlockRows)),
+                    static_cast<unsigned>(div_up(cols, Schedule::kBlockCols)), 1u);
+    q4_rowsplit_gemm_mma_kernel<Schedule, Full><<<grid, Schedule::kThreads, 0, stream>>>(
+        static_cast<const __nv_bfloat16*>(x.data), static_cast<const std::uint8_t*>(w.qdata),
+        static_cast<const std::uint8_t*>(w.scales), static_cast<__nv_bfloat16*>(out.data), rows, k,
+        cols, padded_k);
+    CUDA_CHECK(cudaGetLastError());
+}
+
+template <class Schedule>
+void launch_route(const Tensor& x, const Weight& w, Tensor& out, cudaStream_t stream) {
+    const bool full =
+        (out.ne[0] % Schedule::kBlockRows) == 0 && (x.ne[1] % Schedule::kBlockCols) == 0;
+    for_each_token_slice(x.ne[1], Schedule::kBlockCols,
+                         [&](std::int32_t offset, std::int32_t count) {
+                             const Tensor x_slice = x.slice(1, offset, count);
+                             Tensor out_slice     = out.slice(1, offset, count);
+                             if (full) {
+                                 launch_schedule<Schedule, true>(x_slice, w, out_slice, stream);
+                             } else {
+                                 launch_schedule<Schedule, false>(x_slice, w, out_slice, stream);
+                             }
+                         });
+}
+#endif
+
+} // namespace
+
+void launch_q4_mma_sm120a_muse_c48(const Tensor& x, const Weight& w, Tensor& out,
+                                   cudaStream_t stream) {
+#if defined(GINFER_COMPILED_CC) && GINFER_COMPILED_CC >= 120
+    if (x.ne[1] <= 40) {
+        launch_route<Q4MmaSm120R32C40Schedule>(x, w, out, stream);
+    } else {
+        launch_route<Q4MmaSm120R32C48Schedule>(x, w, out, stream);
+    }
+#else
+    (void)x;
+    (void)w;
+    (void)out;
+    (void)stream;
+    throw std::invalid_argument("Q4 Linear SM120a Muse C48 route requires sm_120a");
+#endif
+}
+
+void launch_q4_mma_sm120a_muse_n19968_t40_bk128(const Tensor& x, const Weight& w, Tensor& out,
+                                                cudaStream_t stream) {
+#if defined(GINFER_COMPILED_CC) && GINFER_COMPILED_CC >= 120
+    launch_route<Q4MmaSm120R64C40K128Schedule>(x, w, out, stream);
+#else
+    (void)x;
+    (void)w;
+    (void)out;
+    (void)stream;
+    throw std::invalid_argument("Q4 Linear SM120a Muse N19968 T40 BK128 route requires sm_120a");
+#endif
+}
+
+} // namespace ginfer::ops::detail

